import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./loader.css";

export type LoaderVariant = "spinner" | "dots" | "bars" | "morph";

const marks = {
  dots: 3,
  bars: 3,
} as const;

export function Loader({
  variant = "spinner",
  size = 20,
  label = "Loading",
  className,
  ...props
}: Omit<ComponentProps<"span">, "children"> & {
  variant?: LoaderVariant;
  size?: number;
  label?: string;
}) {
  const count = variant === "dots" || variant === "bars" ? marks[variant] : 0;
  return (
    <span
      role="status"
      aria-label={label}
      data-slot="loader"
      data-variant={variant}
      className={cn("inline-flex items-center justify-center text-foreground", className)}
      style={{ width: size, height: size }}
      {...props}
    >
      {variant === "spinner" && <span data-slot="loader-spinner" />}
      {variant === "morph" && <span data-slot="loader-morph" />}
      {count > 0 &&
        Array.from({ length: count }, (_, index) => (
          <span
            key={index}
            data-slot={variant === "dots" ? "loader-dot" : "loader-bar"}
            style={{ animationDelay: `calc(${index} * var(--delay-stagger))` }}
          />
        ))}
    </span>
  );
}

/* loader.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loader"][data-variant="dots"],
  [data-slot="loader"][data-variant="bars"] {
    gap: 12%;
  }
  [data-slot="loader-spinner"] {
    width: 100%;
    height: 100%;
    border: 2px solid color-mix(in srgb, currentColor 28%, transparent);
    border-top-color: currentColor;
    border-radius: 50%;
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }
  [data-slot="loader-dot"] {
    width: 22%;
    height: 22%;
    border-radius: 50%;
    background: currentColor;
    animation: caliper-loader-dot var(--duration-loading) var(--ease-in-out) infinite;
  }
  [data-slot="loader-bar"] {
    width: 18%;
    height: 100%;
    transform-origin: center bottom;
    border-radius: var(--radius-control);
    background: currentColor;
    animation: caliper-loader-bar var(--duration-loading) var(--ease-in-out) infinite;
  }
  [data-slot="loader-morph"] {
    width: 68%;
    height: 68%;
    background: currentColor;
    animation: caliper-loader-morph var(--duration-loading) var(--ease-settle) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loader-spinner"],
    [data-slot="loader-dot"],
    [data-slot="loader-bar"],
    [data-slot="loader-morph"] {
      animation: none;
      transition: none;
      transform: none;
    }
  }
}

@keyframes caliper-loader-dot {
  0%,
  80%,
  100% {
    opacity: 0.3;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-25%);
  }
}

@keyframes caliper-loader-bar {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

@keyframes caliper-loader-morph {
  0%,
  100% {
    border-radius: 50%;
    transform: scale(0.72);
  }
  50% {
    border-radius: var(--radius-control);
    transform: scale(1);
  }
}
